settings.custom_css:
/* ===== Venus legal page (vshp) - generated by _build/make-legal-pages.mjs ===== */
body{background-color:#FFFBE9}
html,body{overflow-x:clip!important;overflow-y:visible!important}
selector{width:calc(100% - 8vw);max-width:1240px;margin:0 auto;padding:24px 0 96px;gap:0;display:block;font-family:var(--e-global-typography-vnsbody-font-family),"Discovery Fs",system-ui,sans-serif;font-size:18px;font-weight:300;line-height:1.6;color:#141414}
selector .elementor-widget{margin:0}
selector a{color:var(--e-global-color-vnsgreen,#3A4831);text-decoration:underline;text-underline-offset:3px}
selector a:hover{color:#2C3624}
selector .vlg-crumbs{display:flex;gap:8px;font-size:15px;color:rgba(20,20,20,.6)}
selector .vlg-crumbs a{color:inherit;text-decoration:none}
selector .vlg-crumbs a:hover{color:var(--e-global-color-vnsgreen,#3A4831);text-decoration:underline}
selector .vlg-crumbs i{font-style:normal;opacity:.5}
selector .vlg-crumbs span{color:#141414}
selector .vlg-head{max-width:820px;margin-top:22px}
selector .vlg-title{margin:0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:64px;line-height:1.05;color:#141414}
selector .vlg-title b{font-weight:inherit;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vlg-lead{margin:18px 0 0;font-size:20px;line-height:1.6;color:rgba(20,20,20,.75)}
selector .vlg-upd{margin:12px 0 0;font-size:15px;color:rgba(20,20,20,.55)}
selector .vlg-grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:64px;align-items:start;margin-top:56px}
selector .vlg-toc{position:sticky;top:120px;padding:24px;border:1px solid rgba(20,20,20,.18);border-radius:16px;background:#fff}
selector .vlg-toc b{display:block;margin-bottom:10px;font-size:16px;font-weight:500}
selector .vlg-toc ol{margin:0;padding:0;list-style:none;counter-reset:t}
selector .vlg-toc li{counter-increment:t;margin:0}
selector .vlg-toc a{display:flex;gap:10px;padding:7px 0;font-size:15px;line-height:1.35;color:rgba(20,20,20,.75);text-decoration:none;border-top:1px solid rgba(20,20,20,.08)}
selector .vlg-toc li:first-child a{border-top:0}
selector .vlg-toc a:before{content:counter(t,decimal-leading-zero);flex:none;color:var(--e-global-color-vnsgreen,#3A4831);font-weight:500}
selector .vlg-toc a:hover{color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vlg-body section{scroll-margin-top:120px;padding:34px 0;border-top:1px solid rgba(20,20,20,.18)}
selector .vlg-body section:first-child{padding-top:0;border-top:0}
selector .vlg-body h2{margin:0 0 14px;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:34px;line-height:1.15;color:#141414}
selector .vlg-body h3{margin:22px 0 8px;font-size:20px;font-weight:500;line-height:1.3}
selector .vlg-body p{margin:0 0 12px}
selector .vlg-body ul{margin:0 0 12px;padding-inline-start:22px}
selector .vlg-body li{margin:0 0 8px}
selector .vlg-body li::marker{color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vlg-body strong{font-weight:500}
selector .vlg-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin:6px 0 18px}
selector .vlg-card{display:flex;flex-direction:column;gap:6px;padding:22px;border:1px solid rgba(20,20,20,.18);border-radius:16px;background:#fff}
selector .vlg-card svg{width:28px;height:28px;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vlg-card small{font-size:15px;color:rgba(20,20,20,.6)}
selector .vlg-card b{font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-size:30px;font-weight:700;line-height:1.1;color:#141414}
selector .vlg-card span{font-size:15px;line-height:1.4;color:rgba(20,20,20,.7)}
selector .vlg-towns{display:flex;flex-wrap:wrap;gap:8px;margin:4px 0 14px;padding:0;list-style:none}
selector .vlg-towns li{margin:0;padding:7px 14px;border:1px solid rgba(20,20,20,.18);border-radius:6px;background:#fff;font-size:16px}
selector .vlg-table{width:100%;margin:6px 0 14px;border-collapse:collapse;font-size:16px}
selector .vlg-table,selector .vlg-table tr,selector .vlg-table td,selector .vlg-table th{border:0!important;background:transparent!important}
selector .vlg-table th,selector .vlg-table td{padding:10px 0!important;border-bottom:1px solid rgba(20,20,20,.1)!important;text-align:right;vertical-align:top}
selector .vlg-table th{width:40%;font-weight:500}
selector .vlg-table.vlg-price th{width:84px;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-size:20px;font-weight:700;color:var(--e-global-color-vnsgreen,#3A4831)}
selector .vlg-note{padding:18px 20px;border-radius:12px;background:#fff;border:1px solid rgba(20,20,20,.18);font-size:16px}
selector .vlg-cta{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-top:40px;padding:34px 36px;border-radius:16px;background:var(--e-global-color-vnsgreen,#3A4831);color:#fff}
selector .vlg-cta h2{margin:0;font-family:"Leon","Discovery Fs",system-ui,sans-serif;font-weight:700;font-size:32px;line-height:1.15;color:#fff}
selector .vlg-cta p{margin:8px 0 0;color:rgba(255,255,255,.8)}
selector .vlg-btns{display:flex;gap:10px;flex-wrap:wrap}
selector .vlg-btn{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;gap:8px;height:52px;padding:0 26px;border-radius:12px;font-size:17px;font-weight:500;line-height:1;white-space:nowrap;text-decoration:none!important;transition:background .15s,color .15s,border-color .15s}
selector .vlg-btn svg{width:20px;height:20px;flex:none}
selector .vlg-btn-cream{background:#FFFBE9;color:#141414!important}
selector .vlg-btn-cream:hover{background:#fff;color:#141414!important}
selector .vlg-btn-line{border:1px solid rgba(255,255,255,.6);color:#fff!important}
selector .vlg-btn-line:hover{background:rgba(255,255,255,.12);color:#fff!important}
@media(max-width:1024px){
selector .vlg-grid{grid-template-columns:minmax(0,1fr);gap:28px;margin-top:36px}
selector .vlg-toc{position:static}
selector .vlg-title{font-size:52px}
}
@media(max-width:767px){
selector{width:calc(100% - 32px);padding:16px 0 64px;font-size:17px}
selector .vlg-title{font-size:40px}
selector .vlg-lead{font-size:18px}
selector .vlg-body h2{font-size:28px}
selector .vlg-cards{grid-template-columns:minmax(0,1fr)}
selector .vlg-cta{flex-direction:column;align-items:stretch;padding:26px 22px}
selector .vlg-cta h2{font-size:26px}
selector .vlg-btn{width:100%}
selector .vlg-table th{width:45%}
selector .vlg-table.vlg-price th{width:64px}
}
